408	/**
409	 * @brief Enable card clock
410	 *
411	 * @param hw    hardware instance address
412	 * @param slot  slot
413	 * @param en    enable / disable
414	 */
415	static inline void sdmmc_ll_enable_card_clock(sdmmc_dev_t *hw, uint32_t slot, bool en)
416	{
417	    if (en) {
418	        hw->clkena.cclk_enable |= BIT(slot);
419	    } else {
420	        hw->clkena.cclk_enable &= ~BIT(slot);
421	    }
422	}
