424	/**
425	 * @brief Set card clock div
426	 *
427	 * @param hw        hardware instance address
428	 * @param slot      slot
429	 * @param card_div  divider value
430	 */
431	static inline void sdmmc_ll_set_card_clock_div(sdmmc_dev_t *hw, uint32_t slot, uint32_t card_div)
432	{
433	    if (slot == 0) {
434	        hw->clksrc.card0 = 0;
435	        HAL_FORCE_MODIFY_U32_REG_FIELD(hw->clkdiv, clk_divider0, card_div);
436	    } else if (slot == 1) {
437	        hw->clksrc.card1 = 1;
438	        HAL_FORCE_MODIFY_U32_REG_FIELD(hw->clkdiv, clk_divider1, card_div);
439	    } else {
440	        HAL_ASSERT(false);
441	    }
442	}
