444	/**
445	 * @brief Get card clock div
446	 *
447	 * @param hw        hardware instance address
448	 * @param slot      slot
449	 *
450	 * @return Divider  value
451	 */
452	static inline uint32_t sdmmc_ll_get_card_clock_div(sdmmc_dev_t *hw, uint32_t slot)
453	{
454	    uint32_t card_div = 0;
455	
456	    if (slot == 0) {
457	        card_div = HAL_FORCE_READ_U32_REG_FIELD(hw->clkdiv, clk_divider0);
458	    } else if (slot == 1) {
459	        card_div = HAL_FORCE_READ_U32_REG_FIELD(hw->clkdiv, clk_divider1);
460	    } else {
461	        HAL_ASSERT(false);
462	    }
463	
464	    return card_div;
465	}
