752	static inline void sdmmc_ll_set_card_width(sdmmc_dev_t *hw, uint32_t slot, sd_bus_width_t width)
753	{
754	    uint16_t mask = 1 << slot;
755	
756	    switch (width) {
757	    case SD_BUS_WIDTH_1_BIT:
758	        hw->ctype.card_width_8 &= ~mask;
759	        hw->ctype.card_width &= ~mask;
760	        break;
761	    case SD_BUS_WIDTH_4_BIT:
762	        hw->ctype.card_width_8 &= ~mask;
763	        hw->ctype.card_width |= mask;
764	        break;
765	    case SD_BUS_WIDTH_8_BIT:
766	        hw->ctype.card_width_8 |= mask;
767	        break;
768	    default:
769	        HAL_ASSERT(false);
770	    }
771	}
