146	esp_err_t sd_host_sdmmc_controller_add_slot(sd_host_ctlr_handle_t ctlr, const sd_host_slot_sdmmc_init_cfg_t *config, sd_host_slot_handle_t *ret_handle)
147	{
148	    esp_err_t ret = ESP_FAIL;
149	    sd_host_sdmmc_ctlr_t *ctlr_ctx = __containerof(ctlr, sd_host_sdmmc_ctlr_t, drv);
150	    ESP_RETURN_ON_FALSE(ctlr && config && ret_handle, ESP_ERR_INVALID_ARG, TAG, "invalid argument: null pointer");
151	    ESP_RETURN_ON_FALSE(config->slot_id >= 0 && config->slot_id < SOC_SDMMC_NUM_SLOTS, ESP_ERR_INVALID_ARG, TAG, "invalid slot id");
152	
153	    sd_host_sdmmc_slot_t *slot = heap_caps_calloc(1, sizeof(sd_host_sdmmc_slot_t), SD_HOST_SDMMC_MEM_ALLOC_CAPS);
154	    ESP_RETURN_ON_FALSE(slot, ESP_ERR_NO_MEM, TAG, "no mem for sd host slot context");
155	
156	    xSemaphoreTake(ctlr_ctx->mutex, portMAX_DELAY);
157	
158	    bool slot_available = false;
159	    portENTER_CRITICAL(&ctlr_ctx->spinlock);
160	    if (!ctlr_ctx->slot[config->slot_id]) {
161	        slot_available = true;
162	        ctlr_ctx->slot[config->slot_id] = slot;
163	    }
164	    portEXIT_CRITICAL(&ctlr_ctx->spinlock);
165	    ESP_GOTO_ON_FALSE(slot_available, ESP_ERR_INVALID_STATE, err, TAG, "slot is not available");
166	
167	    portENTER_CRITICAL(&ctlr_ctx->spinlock);
168	    slot->slot_id = config->slot_id;
169	    slot->sd_mode = config->sd_mode;
170	    slot->freq.freq_hz = 400 * 1000;
171	    slot->freq.freq_state = SD_HOST_SLOT_STATE_INIT;
172	    slot->ctlr = ctlr_ctx;
173	    ctlr_ctx->registered_slot_nums = ctlr_ctx->registered_slot_nums + 1;
174	
175	    slot->drv.configure = sd_host_slot_sdmmc_configure;
176	    slot->drv.do_transaction = sd_host_slot_sdmmc_do_transaction;
177	    slot->drv.register_cbs = sd_host_slot_sdmmc_register_event_callbacks;
178	    slot->drv.remove_slot = sd_host_controller_remove_sdmmc_slot;
179	    slot->drv.set_cclk_always_on = sd_host_slot_sdmmc_set_cclk_always_on;
180	    slot->drv.enable_io_int = sd_host_slot_sdmmc_io_int_enable;
181	    slot->drv.wait_io_int = sd_host_slot_sdmmc_io_int_wait;
182	    slot->drv.get_info = sd_host_slot_sdmmc_get_info;
183	    portEXIT_CRITICAL(&ctlr_ctx->spinlock);
184	
185	    ESP_GOTO_ON_ERROR(sdmmc_slot_io_config(slot, config), err, TAG, "failed to config slot io");
186	
187	    portENTER_CRITICAL(&ctlr_ctx->spinlock);
188	    if (ctlr_ctx->registered_slot_nums == 1) {
189	        sdmmc_ll_clear_interrupt(ctlr_ctx->hal.dev, 0xffffffff);
190	        sdmmc_ll_enable_interrupt(ctlr_ctx->hal.dev, SDMMC_LL_EVENT_DEFAULT, true);
191	        sdmmc_ll_enable_global_interrupt(ctlr_ctx->hal.dev, true);
192	    }
193	    portEXIT_CRITICAL(&ctlr_ctx->spinlock);
194	
195	    *ret_handle = &slot->drv;
196	
197	    xSemaphoreGive(ctlr_ctx->mutex);
198	    return ESP_OK;
199	
200	err:
201	    if (slot_available) {
202	        portENTER_CRITICAL(&ctlr_ctx->spinlock);
203	        ctlr_ctx->slot[config->slot_id] = NULL;
204	        ctlr_ctx->registered_slot_nums -= 1;
205	        portEXIT_CRITICAL(&ctlr_ctx->spinlock);
206	    }
207	    xSemaphoreGive(ctlr_ctx->mutex);
208	    free(slot);
209	
210	    return ret;
211	}
