344	static esp_err_t sd_host_controller_remove_sdmmc_slot(sd_host_slot_handle_t slot)
345	{
346	    ESP_RETURN_ON_FALSE(slot, ESP_ERR_INVALID_ARG, TAG, "invalid argument: null pointer");
347	    sd_host_sdmmc_slot_t *slot_ctx = __containerof(slot, sd_host_sdmmc_slot_t, drv);
348	    sd_host_sdmmc_ctlr_t *ctlr = slot_ctx->ctlr;
349	
350	    xSemaphoreTake(ctlr->mutex, portMAX_DELAY);
351	
352	    bool slot_registered = false;
353	    bool no_registered_slots = false;
354	    portENTER_CRITICAL(&ctlr->spinlock);
355	    if (ctlr->slot[slot_ctx->slot_id]) {
356	        slot_registered = true;
357	        ctlr->slot[slot_ctx->slot_id] = NULL;
358	        ctlr->registered_slot_nums -= 1;
359	        no_registered_slots = (ctlr->registered_slot_nums == 0);
360	        if (no_registered_slots) {
361	            sdmmc_ll_enable_global_interrupt(ctlr->hal.dev, false);
362	            sdmmc_ll_enable_interrupt(ctlr->hal.dev, 0xffffffff, false);
363	            sdmmc_ll_clear_interrupt(ctlr->hal.dev, 0xffffffff);
364	            sdmmc_ll_clear_idsts_interrupt(ctlr->hal.dev, 0xffffffff);
365	        }
366	    }
367	    portEXIT_CRITICAL(&ctlr->spinlock);
368	    if (!slot_registered) {
369	        xSemaphoreGive(ctlr->mutex);
370	        ESP_LOGE(TAG, "slot is not registered");
371	        return ESP_ERR_INVALID_STATE;
372	    }
373	
374	    if (slot_ctx->io_config.clk_io != GPIO_NUM_NC) {
375	        gpio_output_disable(slot_ctx->io_config.clk_io);
376	    }
377	    if (slot_ctx->io_config.cmd_io != GPIO_NUM_NC) {
378	        gpio_output_disable(slot_ctx->io_config.cmd_io);
379	    }
380	    if (slot_ctx->io_config.cd_io != GPIO_NUM_NC) {
381	        gpio_output_disable(slot_ctx->io_config.cd_io);
382	    }
383	    if (slot_ctx->io_config.wp_io != GPIO_NUM_NC) {
384	        gpio_output_disable(slot_ctx->io_config.wp_io);
385	    }
386	    if (slot_ctx->io_config.width >= 1) {
387	        gpio_output_disable(slot_ctx->io_config.d0_io);
388	    }
389	    if (slot_ctx->io_config.width >= 4) {
390	        gpio_output_disable(slot_ctx->io_config.d1_io);
391	        gpio_output_disable(slot_ctx->io_config.d2_io);
392	        gpio_output_disable(slot_ctx->io_config.d3_io);
393	    }
394	    if (slot_ctx->io_config.width == 8) {
395	        gpio_output_disable(slot_ctx->io_config.d4_io);
396	        gpio_output_disable(slot_ctx->io_config.d5_io);
397	        gpio_output_disable(slot_ctx->io_config.d6_io);
398	        gpio_output_disable(slot_ctx->io_config.d7_io);
399	    }
400	
401	    xSemaphoreGive(ctlr->mutex);
402	    free(slot);
403	
404	    return ESP_OK;
405	}
