407	static esp_err_t sd_host_del_sdmmc_controller(sd_host_ctlr_handle_t ctlr)
408	{
409	    esp_err_t ret = ESP_OK;
410	    sd_host_sdmmc_ctlr_t *ctlr_ctx = __containerof(ctlr, sd_host_sdmmc_ctlr_t, drv);
411	    ESP_RETURN_ON_FALSE(ctlr, ESP_ERR_INVALID_ARG, TAG, "invalid argument: null pointer");
412	
413	    if (ctlr_ctx->mutex) {
414	        xSemaphoreTake(ctlr_ctx->mutex, portMAX_DELAY);
415	    }
416	
417	    ESP_GOTO_ON_FALSE(ctlr_ctx->registered_slot_nums == 0, ESP_ERR_INVALID_STATE, err, TAG, "host controller with slot registered");
418	    ESP_GOTO_ON_ERROR(sd_host_declaim_controller(ctlr_ctx), err, TAG, "controller isn't in use");
419	    ESP_GOTO_ON_ERROR(esp_intr_free(ctlr_ctx->intr_handle), err, TAG, "failed to delete interrupt service");
420	
421	    sdmmc_hal_deinit(&ctlr_ctx->hal);
422	
423	    if (ctlr_ctx->event_queue) {
424	        vQueueDeleteWithCaps(ctlr_ctx->event_queue);
425	    }
426	    if (ctlr_ctx->io_intr_sem) {
427	        vSemaphoreDeleteWithCaps(ctlr_ctx->io_intr_sem);
428	    }
429	#if CONFIG_PM_ENABLE
430	    if (ctlr_ctx->pm_lock) {
431	        esp_pm_lock_delete(ctlr_ctx->pm_lock);
432	    }
433	#endif
434	
435	#if SDMMC_LL_MPLL_SUPPORTED
436	    esp_clk_tree_enable_src(SOC_MOD_CLK_MPLL, false);
437	#endif
438	
439	    if (ctlr_ctx->mutex) {
440	        vSemaphoreDeleteWithCaps(ctlr_ctx->mutex);
441	    }
442	
443	    free(ctlr_ctx->dma_desc);
444	    ctlr_ctx->dma_desc = NULL;
445	    free(ctlr_ctx);
446	    ctlr_ctx = NULL;
447	
448	    return ESP_OK;
449	
450	err:
451	    if (ctlr_ctx->mutex) {
452	        xSemaphoreGive(ctlr_ctx->mutex);
453	    }
454	    return ret;
455	}
