465	
466	static esp_err_t sd_host_slot_sdmmc_io_int_wait(sd_host_slot_handle_t slot, TickType_t timeout_ticks)
467	{
468	    ESP_RETURN_ON_FALSE(slot, ESP_ERR_INVALID_ARG, TAG, "invalid argument: null pointer");
469	    esp_err_t ret = ESP_FAIL;
470	    sd_host_sdmmc_slot_t *slot_ctx = __containerof(slot, sd_host_sdmmc_slot_t, drv);
471	
472	    /* SDIO interrupts are negedge sensitive ones: the status bit is only set
473	     * when first interrupt triggered.
474	     *
475	     * If D1 GPIO is low when entering this function, we know that interrupt
476	     * (in SDIO sense) has occurred and we don't need to use SDMMC peripheral
477	     * interrupt.
478	     */
479	
480	    /* Disable SDIO interrupt */
481	    if (slot_ctx->slot_id == 0) {
482	        sdmmc_ll_enable_interrupt(slot_ctx->ctlr->hal.dev, SDMMC_INTMASK_IO_SLOT0, false);
483	        sdmmc_ll_clear_interrupt(slot_ctx->ctlr->hal.dev, SDMMC_INTMASK_IO_SLOT0);
484	    } else {
485	        sdmmc_ll_enable_interrupt(slot_ctx->ctlr->hal.dev, SDMMC_INTMASK_IO_SLOT1, false);
486	        sdmmc_ll_clear_interrupt(slot_ctx->ctlr->hal.dev, SDMMC_INTMASK_IO_SLOT1);
487	    }
488	
489	    if (gpio_get_level(slot_ctx->io_config.d1_io) == 0) {
490	        return ESP_OK;
491	    }
492	    /* Otherwise, need to wait for an interrupt. Since D1 was high,
493	     * SDMMC peripheral interrupt is guaranteed to trigger on negedge.
494	     */
495	    xSemaphoreTake(slot_ctx->ctlr->io_intr_sem, 0);
496	
497	    /* Re-enable SDIO interrupt */
498	    if (slot_ctx->slot_id == 0) {
499	        sdmmc_ll_enable_interrupt(slot_ctx->ctlr->hal.dev, SDMMC_INTMASK_IO_SLOT0, true);
500	    } else {
501	        sdmmc_ll_enable_interrupt(slot_ctx->ctlr->hal.dev, SDMMC_INTMASK_IO_SLOT1, true);
502	    }
503	
504	    if (xSemaphoreTake(slot_ctx->ctlr->io_intr_sem, timeout_ticks) == pdTRUE) {
505	        ret = ESP_OK;
506	    } else {
507	        ret = ESP_ERR_TIMEOUT;
508	    }
509	
510	    return ret;
511	}
