544	bool sd_host_check_buffer_alignment(sd_host_sdmmc_slot_t *slot, const void *buf, size_t size)
545	{
546	    //for future-proof
547	    (void)slot;
548	    if (!buf || !size) {
549	        return false;
550	    }
551	
552	    uintptr_t start = (uintptr_t) buf;
553	    if (size - 1 > UINTPTR_MAX - start) {
554	        return false;
555	    }
556	    const void *end = (const void *)(start + size - 1);
557	
558	    bool not_dma_accessible = !sdmmc_dma_accessible(buf) || !sdmmc_dma_accessible(end);
559	    bool different_memory_types = esp_ptr_external_ram(buf) != esp_ptr_external_ram(end);
560	    if (not_dma_accessible || different_memory_types) {
561	        return false;
562	    }
563	
564	    esp_err_t ret = ESP_FAIL;
565	    int cache_flags = 0;
566	    size_t cache_alignment_bytes = 0;
567	    if (esp_ptr_external_ram(buf)) {
568	        cache_flags |= MALLOC_CAP_SPIRAM;
569	    }
570	    ret = esp_cache_get_alignment(cache_flags, &cache_alignment_bytes);
571	    assert(ret == ESP_OK);
572	    (void)ret;
573	
574	    bool is_aligned = false;
575	    size_t alignment = 0;
576	
577	    if (cache_alignment_bytes != 0) {
578	        alignment = cache_alignment_bytes;
579	    } else {
580	        alignment = SDMMC_DMA_ALIGNMENT;
581	    }
582	
583	    is_aligned = ((intptr_t)buf % alignment == 0) && (size % alignment == 0);
584	
585	    return is_aligned;
586	}
