659	    int host_div = 0;
660	    int card_div = 0;
661	    sd_host_slot_get_clk_dividers(slot, slot->freq.freq_hz / 1000, &host_div, &card_div, &clk_src);
662	    *real_freq_khz = sd_host_calc_freq(slot->clk_src, host_div, card_div);
