846	static esp_err_t sd_host_claim_controller(sd_host_sdmmc_ctlr_t *controller)
847	{
848	    assert(controller);
849	
850	    _lock_acquire(&s_platform.mutex);
851	    bool found = false;
852	    for (int i = 0; i < SDMMC_LL_HOST_CTLR_NUMS; i ++) {
853	        found = !s_platform.controllers[i];
854	        if (found) {
855	            s_platform.controllers[i] = controller;
856	            controller->host_id = i;
857	            PERIPH_RCC_ATOMIC() {
858	                sdmmc_ll_enable_bus_clock(i, true);
859	                sdmmc_ll_reset_register(i);
860	            }
861	            break;
862	        }
863	    }
864	    _lock_release(&s_platform.mutex);
865	
866	    if (!found) {
867	        return ESP_ERR_NOT_FOUND;
868	    }
869	    return ESP_OK;
870	}
