1062	/*---------------------------------------------------------------
1063	                    Static: Clock
1064	---------------------------------------------------------------*/
1065	/* We have two clock divider stages:
1066	 * - one is the clock generator which drives SDMMC peripheral,
1067	 *   it can be configured using SDMMC.clock register. It can generate
1068	 *   frequencies 160MHz/(N + 1), where 0 < N < 16, I.e. from 10 to 80 MHz.
1069	 * - 4 clock dividers inside SDMMC peripheral, which can divide clock
1070	 *   from the first stage by 2 * M, where 0 < M < 255
1071	 *   (they can also be bypassed).
1072	 *
1073	 * For cards which aren't UHS-1 or UHS-2 cards, which we don't support,
1074	 * maximum bus frequency in high speed (HS) mode is 50 MHz.
1075	 * Note: for non-UHS-1 cards, HS mode is optional.
1076	 * Default speed (DS) mode is mandatory, it works up to 25 MHz.
1077	 * Whether the card supports HS or not can be determined using TRAN_SPEED
1078	 * field of card's CSD register.
1079	 *
1080	 * 50 MHz can not be obtained exactly, closest we can get is 53 MHz.
1081	 *
1082	 * The first stage divider is set to the highest possible value for the given
1083	 * frequency, and the the second stage dividers are used if division factor
1084	 * is >16.
1085	 *
1086	 * Of the second stage dividers, div0 is used for card 0, and div1 is used
1087	 * for card 1.
1088	 */
1089	static void sd_host_set_clk_div(sd_host_sdmmc_ctlr_t *ctlr, soc_periph_sdmmc_clk_src_t src, int div)
1090	{
1091	    ESP_ERROR_CHECK(esp_clk_tree_enable_src((soc_module_clk_t)src, true));
1092	    PERIPH_RCC_ATOMIC() {
1093	        sdmmc_ll_set_clock_div(ctlr->hal.dev, div);
1094	        sdmmc_ll_select_clk_source(ctlr->hal.dev, src);
1095	        sdmmc_ll_init_phase_delay(ctlr->hal.dev);
1096	#if SDMMC_LL_SDIO_PLL_SUPPORTED
1097	        if (src == SDMMC_CLK_SRC_SDIO_200M) {
1098	            sdmmc_ll_enable_sdio_pll(ctlr->hal.dev, true);
1099	        }
1100	#endif
1101	    }
1102	
1103	    // Wait for the clock to propagate
1104	    esp_rom_delay_us(10);
1105	}
1106	
1107	static void sd_host_slot_get_clk_dividers(sd_host_sdmmc_slot_t *slot, uint32_t freq_khz, int *host_div, int *card_div, soc_periph_sdmmc_clk_src_t *src)
1108	{
1109	    uint32_t clk_src_freq_hz = 0;
1110	    soc_periph_sdmmc_clk_src_t clk_src = 0;
1111	#if SOC_SDMMC_UHS_I_SUPPORTED && SDMMC_LL_SDIO_PLL_SUPPORTED
1112	    if (freq_khz > SDMMC_FREQ_HIGHSPEED) {
1113	        clk_src = SDMMC_CLK_SRC_SDIO_200M;
1114	    } else
1115	#endif
1116	    {
1117	        clk_src = SDMMC_CLK_SRC_DEFAULT;
1118	    }
1119	    slot->clk_src = clk_src;
1120	
1121	    esp_err_t ret = esp_clk_tree_src_get_freq_hz(clk_src, ESP_CLK_TREE_SRC_FREQ_PRECISION_CACHED, &clk_src_freq_hz);
1122	    assert(ret == ESP_OK);
1123	    (void)ret;
1124	    ESP_LOGD(TAG, "clk_src_freq_hz: %"PRId32" hz", clk_src_freq_hz);
1125	
1126	#if SDMMC_LL_MAX_FREQ_KHZ_FPGA
1127	    if (freq_khz >= SDMMC_LL_MAX_FREQ_KHZ_FPGA) {
1128	        ESP_LOGW(TAG, "working on FPGA, fallback to use the %d KHz", SDMMC_LL_MAX_FREQ_KHZ_FPGA);
1129	        freq_khz = SDMMC_LL_MAX_FREQ_KHZ_FPGA;
1130	    }
1131	#endif
1132	
1133	    // Calculate new dividers
1134	#if SOC_SDMMC_UHS_I_SUPPORTED
1135	    if (freq_khz == SDMMC_FREQ_SDR104) {
1136	        *host_div = clk_src_freq_hz / 200000000;
1137	        *card_div = 0;
1138	    } else if (freq_khz == SDMMC_FREQ_SDR50) {
1139	        *host_div = clk_src_freq_hz / 100000000;
1140	        *card_div = 0;
1141	    } else
1142	#endif
1143	#if !SDMMC_LL_MPLL_SUPPORTED
1144	        if (freq_khz >= SDMMC_FREQ_HIGHSPEED) {
1145	            *host_div = 4;       // src_freq_hz / 4 = 40 MHz
1146	            *card_div = 0;
1147	        } else if (freq_khz == SDMMC_FREQ_DEFAULT) {
1148	            *host_div = 8;       // src_freq_hz / 8 = 20 MHz
1149	            *card_div = 0;
1150	        } else if (freq_khz == SDMMC_FREQ_PROBING) {
1151	            *host_div = 10;      // src_freq_hz / 10 / (20 * 2) = 400 kHz
1152	            *card_div = 20;
1153	        } else
1154	#endif
1155	        {
1156	            uint32_t target_hz = (uint32_t)freq_khz * 1000;
1157	            // host_div: 1..16 (4-bit edge regs), card_div: 0=bypass or 1..255 (actual div = 2*card_div)
1158	            // actual_freq = clk_src / host_div                   when card_div == 0
1159	            // actual_freq = clk_src / host_div / (2 * card_div)  when card_div > 0
1160	            uint32_t total_div = (clk_src_freq_hz + target_hz - 1) / target_hz;
1161	
1162	            if (total_div <= 16) {
1163	                *host_div = (int)total_div;
1164	                *card_div = 0;
1165	            } else {
1166	                // Two-stage: smallest host_div keeps highest intermediate freq for best precision
1167	                *host_div = 2;
1168	                *card_div = 255;
1169	                for (int h = 2; h <= 16; h++) {
1170	                    uint32_t intermediate = clk_src_freq_hz / h;
1171	                    int c = (int)((intermediate + 2 * target_hz - 1) / (2 * target_hz));
1172	                    if (c < 1) {
1173	                        c = 1;
1174	                    }
1175	                    if (c <= 255) {
1176	                        *host_div = h;
1177	                        *card_div = c;
1178	                        break;
1179	                    }
1180	                }
1181	            }
1182	        }
1183	
1184	    ESP_LOGD(TAG, "host_div: %d, card_div: %d", *host_div, *card_div);
1185	
1186	    *src = clk_src;
1187	}
1188	
1189	static int sd_host_calc_freq(soc_periph_sdmmc_clk_src_t src, const int host_div, const int card_div)
1190	{
1191	    uint32_t clk_src_freq_hz = 0;
1192	    esp_err_t ret = esp_clk_tree_src_get_freq_hz(src, ESP_CLK_TREE_SRC_FREQ_PRECISION_CACHED, &clk_src_freq_hz);
1193	    assert(ret == ESP_OK);
1194	    (void)ret;
1195	
1196	    return clk_src_freq_hz / host_div / ((card_div == 0) ? 1 : card_div * 2) / 1000;
1197	}
