1202	static void configure_pin_iomux(uint8_t gpio_num)
1203	{
1204	    assert(gpio_num != (uint8_t) GPIO_NUM_NC);
1205	    gpio_pulldown_dis(gpio_num);
1206	    gpio_input_enable(gpio_num);
1207	    gpio_iomux_output(gpio_num, SDMMC_LL_IOMUX_FUNC);
1208	#if !CONFIG_IDF_TARGET_ESP32
1209	    /**
1210	     * On ESP32, the default pin drive value (2) works
1211	     */
1212	    gpio_set_drive_capability(gpio_num, 3);
1213	#endif
1214	}
1215	
1216	static void configure_pin_gpio_matrix(uint8_t gpio_num, uint8_t gpio_matrix_sig, gpio_mode_t mode, const char *name)
1217	{
1218	    assert(gpio_num != (uint8_t) GPIO_NUM_NC);
1219	    ESP_LOGD(TAG, "using GPIO%d as %s pin", gpio_num, name);
1220	    //todo: IDF-11125
1221	    gpio_reset_pin(gpio_num);
1222	    gpio_set_direction(gpio_num, mode);
1223	    gpio_pulldown_dis(gpio_num);
1224	    if (mode == GPIO_MODE_INPUT || mode == GPIO_MODE_INPUT_OUTPUT) {
1225	        esp_rom_gpio_connect_in_signal(gpio_num, gpio_matrix_sig, false);
1226	    }
1227	    if (mode == GPIO_MODE_OUTPUT || mode == GPIO_MODE_INPUT_OUTPUT) {
1228	        esp_rom_gpio_connect_out_signal(gpio_num, gpio_matrix_sig, false, false);
1229	    }
1230	}
1231	
1232	static void configure_pin(uint8_t gpio_num, uint8_t gpio_matrix_sig, gpio_mode_t mode, const char *name, bool use_gpio_matrix)
1233	{
1234	    if (use_gpio_matrix) {
1235	        configure_pin_gpio_matrix(gpio_num, gpio_matrix_sig, mode, name);
1236	    } else {
1237	        configure_pin_iomux(gpio_num);
1238	    }
1239	}
