1241	//True: pins are all not set; False: one or more pins are set
1242	static bool s_check_pin_not_set(const sd_host_sdmmc_slot_io_cfg_t *io_config)
1243	{
1244	#if SOC_SDMMC_USE_GPIO_MATRIX
1245	    bool pin_not_set = !io_config->clk_io && !io_config->cmd_io && !io_config->d0_io && !io_config->d1_io && !io_config->d2_io &&
1246	                       !io_config->d3_io && !io_config->d4_io && !io_config->d5_io && !io_config->d6_io && !io_config->d7_io;
1247	    return pin_not_set;
1248	#else
1249	    return true;
1250	#endif
1251	}
