1253	static esp_err_t sdmmc_host_pullup_en_internal(sd_host_sdmmc_slot_t *slot)
1254	{
1255	    if (slot->width.width > sdmmc_slot_info[slot->slot_id].width) {
1256	        //in esp32 we only support 8 bit in slot 0, note this is occupied by the flash by default
1257	        return ESP_ERR_INVALID_ARG;
1258	    }
1259	    // according to the spec, the host controls the clk, we don't to pull it up here
1260	    gpio_pullup_en(slot->io_config.cmd_io);
1261	    gpio_pullup_en(slot->io_config.d0_io);
1262	    if (slot->width.width >= 4) {
1263	        gpio_pullup_en(slot->io_config.d1_io);
1264	        gpio_pullup_en(slot->io_config.d2_io);
1265	        gpio_pullup_en(slot->io_config.d3_io);
1266	    }
1267	    if (slot->width.width == 8) {
1268	        gpio_pullup_en(slot->io_config.d4_io);
1269	        gpio_pullup_en(slot->io_config.d5_io);
1270	        gpio_pullup_en(slot->io_config.d6_io);
1271	        gpio_pullup_en(slot->io_config.d7_io);
1272	    }
1273	    return ESP_OK;
1274	}
