1276	static esp_err_t sdmmc_slot_io_config(sd_host_sdmmc_slot_t *slot, const sd_host_slot_sdmmc_init_cfg_t *slot_init_config)
1277	{
1278	    bool gpio_wp_polarity = slot_init_config->slot_flags.wp_active_high;
1279	    sd_bus_width_t slot_width = slot_init_config->io_config.width;
1280	    int slot_id = slot_init_config->slot_id;
1281	
1282	    const sdmmc_slot_info_t *slot_info = &sdmmc_slot_info[slot_id];
1283	    ESP_RETURN_ON_FALSE(slot_width <= slot_info->width, ESP_ERR_INVALID_ARG, TAG, "wrong slot width");
1284	    if (slot_width == SD_HOST_SLOT_WIDTH_DEFAULT) {
1285	        slot_width = slot_info->width;
1286	    }
1287	
1288	    const sd_host_sdmmc_slot_io_cfg_t *io_config = &slot_init_config->io_config;
1289	    sd_host_sdmmc_slot_io_cfg_t *slot_gpio = &slot->io_config;
1290	
1291	    slot->io_config.clk_io = GPIO_NUM_NC;
1292	    slot->io_config.cmd_io = GPIO_NUM_NC;
1293	    slot->io_config.cd_io = GPIO_NUM_NC;
1294	    slot->io_config.wp_io = GPIO_NUM_NC;
1295	    slot->io_config.d0_io = GPIO_NUM_NC;
1296	    slot->io_config.d1_io = GPIO_NUM_NC;
1297	    slot->io_config.d2_io = GPIO_NUM_NC;
1298	    slot->io_config.d3_io = GPIO_NUM_NC;
1299	    slot->io_config.d4_io = GPIO_NUM_NC;
1300	    slot->io_config.d5_io = GPIO_NUM_NC;
1301	    slot->io_config.d6_io = GPIO_NUM_NC;
1302	    slot->io_config.d7_io = GPIO_NUM_NC;
1303	    slot->width.width = slot_width;
1304	    slot->width.width_state = SD_HOST_SLOT_STATE_INIT;
1305	    slot_gpio->cd_io = io_config->cd_io;
1306	    slot_gpio->wp_io = io_config->wp_io;
1307	
1308	    bool pin_not_set = s_check_pin_not_set(io_config);
1309	    //SD driver behaviour is: all pins not defined == using iomux
1310	    bool use_gpio_matrix = !pin_not_set;
1311	
1312	    if (slot_id == 0) {
1313	#if !SDMMC_LL_SLOT_SUPPORT_GPIO_MATRIX(0)
1314	        if (use_gpio_matrix) {
1315	            if (slot_width >= 1) {
1316	                if (SDMMC_SLOT0_IOMUX_PIN_NUM_CLK == io_config->clk_io && SDMMC_SLOT0_IOMUX_PIN_NUM_CMD == io_config->cmd_io && SDMMC_SLOT0_IOMUX_PIN_NUM_D0 == io_config->d0_io) {
1317	                    use_gpio_matrix = false;
1318	                } else {
1319	                    use_gpio_matrix = true;
1320	                }
1321	            }
1322	            if (slot_width >= 4) {
1323	                if (SDMMC_SLOT0_IOMUX_PIN_NUM_D1 == io_config->d1_io && SDMMC_SLOT0_IOMUX_PIN_NUM_D2 == io_config->d2_io && SDMMC_SLOT0_IOMUX_PIN_NUM_D3 == io_config->d3_io) {
1324	                    use_gpio_matrix = false;
1325	                } else {
1326	                    use_gpio_matrix = true;
1327	                }
1328	            }
1329	        } else {
1330	            ESP_RETURN_ON_FALSE(!use_gpio_matrix, ESP_ERR_INVALID_ARG, TAG, "doesn't support routing from GPIO matrix, driver uses dedicated IOs");
1331	        }
1332	#endif
1333	    } else {
1334	#if !SDMMC_LL_SLOT_SUPPORT_GPIO_MATRIX(1)
1335	        ESP_RETURN_ON_FALSE(!use_gpio_matrix, ESP_ERR_INVALID_ARG, TAG, "doesn't support routing from GPIO matrix, driver uses dedicated IOs");
1336	#endif
1337	    }
1338	    slot->use_gpio_matrix = use_gpio_matrix;
1339	
1340	#if SOC_SDMMC_USE_GPIO_MATRIX
1341	    if (use_gpio_matrix) {
1342	        /* Save pin configuration for this slot */
1343	        slot_gpio->clk_io = io_config->clk_io;
1344	        slot_gpio->cmd_io = io_config->cmd_io;
1345	        slot_gpio->d0_io = io_config->d0_io;
1346	        /* Save d1 even in 1-line mode, it might be needed for SDIO INT line */
1347	        slot_gpio->d1_io = io_config->d1_io;
1348	        if (slot_width >= 4) {
1349	            slot_gpio->d2_io = io_config->d2_io;
1350	        }
1351	        /* Save d3 even for 1-line mode, as it needs to be set high */
1352	        slot_gpio->d3_io = io_config->d3_io;
1353	        if (slot_width >= 8) {
1354	            slot_gpio->d4_io = io_config->d4_io;
1355	            slot_gpio->d5_io = io_config->d5_io;
1356	            slot_gpio->d6_io = io_config->d6_io;
1357	            slot_gpio->d7_io = io_config->d7_io;
1358	        }
1359	    } else
1360	#endif  //#if SOC_SDMMC_USE_GPIO_MATRIX
1361	    {
1362	        /* init pin configuration for this slot */
1363	        slot_gpio->clk_io = sdmmc_slot_gpio_num[slot_id].clk;
1364	        slot_gpio->cmd_io = sdmmc_slot_gpio_num[slot_id].cmd;
1365	        slot_gpio->d0_io = sdmmc_slot_gpio_num[slot_id].d0;
1366	        slot_gpio->d1_io = sdmmc_slot_gpio_num[slot_id].d1;
1367	        slot_gpio->d2_io = sdmmc_slot_gpio_num[slot_id].d2;
1368	        slot_gpio->d3_io = sdmmc_slot_gpio_num[slot_id].d3;
1369	        slot_gpio->d4_io = sdmmc_slot_gpio_num[slot_id].d4;
1370	        slot_gpio->d5_io = sdmmc_slot_gpio_num[slot_id].d5;
1371	        slot_gpio->d6_io = sdmmc_slot_gpio_num[slot_id].d6;
1372	        slot_gpio->d7_io = sdmmc_slot_gpio_num[slot_id].d7;
1373	    }
1374	
1375	    bool pullup = slot_init_config->slot_flags.internal_pullup;
1376	    if (pullup) {
1377	        sdmmc_host_pullup_en_internal(slot);
1378	    }
1379	
1380	    if (slot_width >= 1) {
1381	        GPIO_NUM_CHECK(slot_gpio->clk_io);
1382	        GPIO_NUM_CHECK(slot_gpio->cmd_io);
1383	        GPIO_NUM_CHECK(slot_gpio->d0_io);
1384	    }
1385	    if (slot_width >= 4) {
1386	        GPIO_NUM_CHECK(slot_gpio->d1_io);
1387	        GPIO_NUM_CHECK(slot_gpio->d2_io);
1388	        GPIO_NUM_CHECK(slot_gpio->d3_io);
1389	    }
1390	    if (slot_width == 8) {
1391	        GPIO_NUM_CHECK(slot_gpio->d4_io);
1392	        GPIO_NUM_CHECK(slot_gpio->d5_io);
1393	        GPIO_NUM_CHECK(slot_gpio->d6_io);
1394	        GPIO_NUM_CHECK(slot_gpio->d7_io);
1395	    }
1396	
1397	    configure_pin(slot_gpio->clk_io, sdmmc_slot_gpio_sig[slot_id].clk, GPIO_MODE_OUTPUT, "clk", use_gpio_matrix);
1398	    configure_pin(slot_gpio->cmd_io, sdmmc_slot_gpio_sig[slot_id].cmd, GPIO_MODE_INPUT_OUTPUT, "cmd", use_gpio_matrix);
1399	    configure_pin(slot_gpio->d0_io, sdmmc_slot_gpio_sig[slot_id].d0, GPIO_MODE_INPUT_OUTPUT, "d0", use_gpio_matrix);
1400	
1401	    if (slot_width >= 4) {
1402	        configure_pin(slot_gpio->d1_io, sdmmc_slot_gpio_sig[slot_id].d1, GPIO_MODE_INPUT_OUTPUT, "d1", use_gpio_matrix);
1403	        configure_pin(slot_gpio->d2_io, sdmmc_slot_gpio_sig[slot_id].d2, GPIO_MODE_INPUT_OUTPUT, "d2", use_gpio_matrix);
1404	        if (slot->sd_mode == SD_MODE_UHS1) {
1405	            configure_pin(slot_gpio->d3_io, sdmmc_slot_gpio_sig[slot_id].d3, GPIO_MODE_INPUT_OUTPUT, "d3", use_gpio_matrix);
1406	        } else {
1407	            // Force D3 high to make slave enter SD mode.
1408	            // Connect to peripheral after width configuration.
1409	            if (slot_gpio->d3_io > GPIO_NUM_NC) {
1410	                gpio_config_t gpio_conf = {
1411	                    .pin_bit_mask = BIT64(slot_gpio->d3_io),
1412	                    .mode = GPIO_MODE_OUTPUT,
1413	                    .pull_up_en = GPIO_PULLUP_DISABLE,
1414	                    .pull_down_en = GPIO_PULLDOWN_DISABLE,
1415	                    .intr_type = GPIO_INTR_DISABLE,
1416	                };
1417	                gpio_config(&gpio_conf);
1418	                gpio_set_level(slot_gpio->d3_io, 1);
1419	            }
1420	        }
1421	    }
1422	    if (slot_width == 8) {
1423	        configure_pin(slot_gpio->d4_io, sdmmc_slot_gpio_sig[slot_id].d4, GPIO_MODE_INPUT_OUTPUT, "d4", use_gpio_matrix);
1424	        configure_pin(slot_gpio->d5_io, sdmmc_slot_gpio_sig[slot_id].d5, GPIO_MODE_INPUT_OUTPUT, "d5", use_gpio_matrix);
1425	        configure_pin(slot_gpio->d6_io, sdmmc_slot_gpio_sig[slot_id].d6, GPIO_MODE_INPUT_OUTPUT, "d6", use_gpio_matrix);
1426	        configure_pin(slot_gpio->d7_io, sdmmc_slot_gpio_sig[slot_id].d7, GPIO_MODE_INPUT_OUTPUT, "d7", use_gpio_matrix);
1427	    }
1428	
1429	    // SDIO slave interrupt is edge sensitive to ~(int_n | card_int | card_detect)
1430	    // set this and card_detect to high to enable sdio interrupt
1431	    esp_rom_gpio_connect_in_signal(GPIO_MATRIX_CONST_ONE_INPUT, slot_info->card_int, false);
1432	
1433	    // Set up Card Detect input
1434	    int matrix_in_cd = 0;
1435	    if (io_config->cd_io != GPIO_NUM_NC) {
1436	        ESP_LOGD(TAG, "using GPIO%d as CD pin", io_config->cd_io);
1437	        esp_rom_gpio_pad_select_gpio(io_config->cd_io);
1438	        gpio_set_direction(io_config->cd_io, GPIO_MODE_INPUT);
1439	        matrix_in_cd = io_config->cd_io;
1440	    } else {
1441	        // if not set, default to CD low (card present)
1442	        matrix_in_cd = GPIO_MATRIX_CONST_ZERO_INPUT;
1443	    }
1444	    esp_rom_gpio_connect_in_signal(matrix_in_cd, slot_info->card_detect, false);
1445	
1446	    // Set up Write Protect input
1447	    int matrix_in_wp;
1448	    if (io_config->wp_io != GPIO_NUM_NC) {
1449	        ESP_LOGD(TAG, "using GPIO%d as WP pin", io_config->wp_io);
1450	        esp_rom_gpio_pad_select_gpio(io_config->wp_io);
1451	        gpio_set_direction(io_config->wp_io, GPIO_MODE_INPUT);
1452	        matrix_in_wp = io_config->wp_io;
1453	    } else {
1454	        // if not set, default to WP high (not write protected)
1455	        matrix_in_wp = GPIO_MATRIX_CONST_ONE_INPUT;
1456	    }
1457	    // As hardware expects an active-high signal,
1458	    // if WP signal is active low, then invert it in GPIO matrix,
1459	    // else keep it in its default state
1460	    esp_rom_gpio_connect_in_signal(matrix_in_wp, slot_info->write_protect, (gpio_wp_polarity ? false : true));
1461	
1462	    return ESP_OK;
1463	}
